docs = [
    "FAISS is a library for efficient similarity search developed by Facebook AI Research.",
    "LangChain provides tools for building RAG pipelines with vector stores and LLMs."
]
rag = SimpleRAG(docs, chunk_size=10, overlap=2)
tests = [
    {"question": "similarity search library", "expected_keywords": ["faiss", "similarity"]},
    {"question": "building RAG pipelines", "expected_keywords": ["langchain", "rag"]}
]
harness = EvalHarness(rag, tests)
result = harness.run(k=2)
print(result["precision"])
print(len(result["details"]))
